def add_workflow_policy_keys(apps, schema_editor):
    AgentPolicy = apps.get_model("agent", "AgentPolicy")
    defaults = {
        "workflowEnabled": True,
        "operatorEnabled": False,
        "maxIterations": 5,
        "maxOperatorSteps": 8,
    }
    for policy in AgentPolicy.objects.all():
        value = dict(policy.value or {})
        changed = False
        for key, default in defaults.items():
            if key not in value:
                value[key] = default
                changed = True
        if changed:
            policy.value = value
            policy.save(update_fields=["value", "updated_at"])


